<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('student');

$statement = db()->prepare("SELECT c.id, c.title, COUNT(DISTINCT l.id) AS total_lessons, COUNT(DISTINCT lp.id) AS completed_lessons FROM enrollments e INNER JOIN courses c ON c.id = e.course_id LEFT JOIN lessons l ON l.course_id = c.id AND l.status = 'published' LEFT JOIN lesson_progress lp ON lp.lesson_id = l.id AND lp.user_id = e.user_id WHERE e.user_id = :user_id AND c.status = 'published' GROUP BY c.id, c.title, e.enrolled_at ORDER BY e.enrolled_at DESC LIMIT 6");
$statement->execute(['user_id' => current_user()['id']]);
$courses = $statement->fetchAll();
$profileStatement = db()->prepare('SELECT total_xp, current_streak, level FROM student_profiles WHERE user_id = :user_id');
$profileStatement->execute(['user_id' => current_user()['id']]);
$profile = $profileStatement->fetch() ?: ['total_xp' => 0, 'current_streak' => 0, 'level' => 1];
$nextLevelXp = ((int)$profile['level']) * 100;
$levelStartXp = max(0, (((int)$profile['level']) - 1) * 100);
$levelProgress = $nextLevelXp > $levelStartXp ? (int)round(((int)$profile['total_xp'] - $levelStartXp) / ($nextLevelXp - $levelStartXp) * 100) : 0;
$quizStatement = db()->prepare('SELECT q.title, qa.percentage, qa.passed, qa.completed_at FROM quiz_attempts qa INNER JOIN quizzes q ON q.id = qa.quiz_id WHERE qa.user_id = :user_id AND qa.completed_at IS NOT NULL ORDER BY qa.completed_at DESC LIMIT 5'); $quizStatement->execute(['user_id' => current_user()['id']]); $quizResults = $quizStatement->fetchAll();
$achievementStatement = db()->prepare('SELECT a.name FROM student_achievements sa INNER JOIN achievements a ON a.id = sa.achievement_id WHERE sa.user_id = :user_id ORDER BY sa.completed_at DESC LIMIT 4'); $achievementStatement->execute(['user_id' => current_user()['id']]); $recentAchievements = $achievementStatement->fetchAll();
$badgeStatement = db()->prepare('SELECT b.name FROM student_badges sb INNER JOIN badges b ON b.id = sb.badge_id WHERE sb.user_id = :user_id ORDER BY sb.awarded_at DESC LIMIT 4'); $badgeStatement->execute(['user_id' => current_user()['id']]); $recentBadges = $badgeStatement->fetchAll();
$pageTitle = 'Student dashboard';
require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h2 fw-bold mb-1">Welcome, <?= e(current_user()['first_name']) ?>.</h1><p class="text-secondary mb-0">Keep your learning momentum going.</p></div><div class="d-flex flex-wrap gap-2"><a class="btn btn-primary" href="<?= e(app_url('student/courses.php')) ?>">Explore courses</a><a class="btn btn-outline-primary" href="<?= e(app_url('student/quizzes.php')) ?>">Take quizzes</a></div></div><div class="row g-4 mb-5"><div class="col-md-4"><div class="card feature-card p-4"><span class="text-secondary">Current XP</span><strong class="display-6"><?= (int)$profile['total_xp'] ?></strong><div class="progress mt-3"><div class="progress-bar" style="width: <?= min(100, max(0, $levelProgress)) ?>%"></div></div><small class="text-secondary mt-2"><?= min(100, max(0, $levelProgress)) ?>% to Level <?= (int)$profile['level'] + 1 ?></small></div></div><div class="col-md-4"><div class="card feature-card p-4"><span class="text-secondary">Daily streak</span><strong class="display-6"><?= (int)$profile['current_streak'] ?> days</strong></div></div><div class="col-md-4"><div class="card feature-card p-4"><span class="text-secondary">Level</span><strong class="display-6"><?= (int)$profile['level'] ?></strong></div></div></div><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4 fw-bold mb-0">My courses</h2><a href="<?= e(app_url('student/courses.php?my=1')) ?>">View all</a></div><div class="row g-4 mb-5"><?php if (!$courses): ?><div class="col-12"><div class="card p-4"><p class="text-secondary mb-0">You have not enrolled in a course yet.</p></div></div><?php endif; ?><?php foreach ($courses as $course): $total = (int)$course['total_lessons']; $completed = (int)$course['completed_lessons']; $progress = $total ? (int)round(($completed / $total) * 100) : 0; ?><div class="col-md-6"><div class="card feature-card h-100 p-4"><div class="d-flex justify-content-between gap-3"><h3 class="h5"><?= e($course['title']) ?></h3><span class="small text-secondary"><?= $progress ?>%</span></div><div class="progress my-3" role="progressbar" aria-label="Course progress" aria-valuenow="<?= $progress ?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width: <?= $progress ?>%"></div></div><p class="small text-secondary mb-3"><?= $completed ?> of <?= $total ?> lessons completed</p><a class="btn btn-outline-primary mt-auto" href="<?= e(app_url('student/course.php?id=' . $course['id'])) ?>">Continue course</a></div></div><?php endforeach; ?></div><div class="row g-4"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Recent quiz results</h2><?php if (!$quizResults): ?><p class="text-secondary">Quiz results will appear here.</p><?php else: ?><?php foreach ($quizResults as $result): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($result['title']) ?></span><span class="<?= $result['passed'] ? 'text-success' : 'text-danger' ?>"><?= e((string)$result['percentage']) ?>%</span></div><?php endforeach; ?><?php endif; ?></div></div></div><div class="col-lg-3"><div class="card h-100"><div class="card-body"><h2 class="h5">Achievements</h2><?php foreach ($recentAchievements as $item): ?><span class="badge text-bg-primary me-1 mb-2"><?= e($item['name']) ?></span><?php endforeach; ?><?php if (!$recentAchievements): ?><p class="text-secondary">None yet.</p><?php endif; ?></div></div></div><div class="col-lg-3"><div class="card h-100"><div class="card-body"><h2 class="h5">Badges</h2><?php foreach ($recentBadges as $item): ?><span class="badge text-bg-success me-1 mb-2"><?= e($item['name']) ?></span><?php endforeach; ?><?php if (!$recentBadges): ?><p class="text-secondary">None yet.</p><?php endif; ?></div></div></div></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
